#include <stdio.h>

int main(void) {
    int A, L, N;
    scanf("%d %d", &A, &L);
    scanf("%d", &N);

    int bestId = -1;
    int bestArea = 0;

    for (int i = 1; i <= N; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);

        int fits = (X >= A && Y >= L) || (X >= L && Y >= A);
        int area = X * Y;

        if (fits && (bestId == -1 || area < bestArea)) {
            bestId = i;
            bestArea = area;
        }
    }

    printf("%d\n", bestId);
    return 0;
}
